    def render_case():
        events=[]
        class Named:
            def __set_name__(self,owner,name):events.append((owner.__name__,name))
        class Mixin:
            __slots__=()
            def greet(self):return "mixin"
            def __init_subclass__(cls):events.append((cls.__name__,"subclass"))
        class BaseDeclaration(Mixin):
            "base documentation"
            units:int=2
            token:int=const(default=3)
            named=Named()
            def greet(self):return super().greet()+"/base"
            @classmethod
            def owner(cls):return __class__.__name__,cls.__name__
            @staticmethod
            def declared():return __class__.__name__
            @property
            def title(self):return __class__.__name__
        original_cell=BaseDeclaration.greet.__closure__[0]
        Base=dataclass(BaseDeclaration)
